<h1><?= te('Employee folders') ?></h1><p class="sub"><?= te('A single record per person with their history across applications and projects.') ?></p><form class="card row" method="get"><input name="q" value="<?= e($search) ?>" placeholder="<?= te('Search by name or email') ?>"><button class="btn"><?= te('Search') ?></button></form><div class="card scroll"><table><tr><th><?= te('Employee') ?></th><th><?= te('Contact') ?></th><th><?= te('Employment') ?></th><th><?= te('Availability / rehire') ?></th><th><?= te('Active assignments') ?></th><th><?= te('Folder') ?></th></tr><?php foreach($employees as $e): ?><tr><td><?= e($e['full_name']) ?></td><td><?= e($e['email']) ?><br><?= e($e['phone']) ?></td><td><?= e($e['employment_type'] ?? 'Not configured') ?></td><td><?= e($e['availability'].' · '.$e['rehire_status']) ?></td><td><?= (int)$e['deployments'] ?></td><td><a href="/employee-folder?id=<?= (int)$e['id'] ?>"><?= te('Open folder') ?></a></td></tr><?php endforeach; ?></table></div><p><?php if($page>1): ?><a href="/employees?page=<?= $page-1 ?>&q=<?= urlencode($search) ?>"><?= te('Previous') ?></a><?php endif; ?> <?php if(count($employees)===100): ?><a href="/employees?page=<?= $page+1 ?>&q=<?= urlencode($search) ?>"><?= te('Next') ?></a><?php endif; ?></p>